<?php
defined('ABSPATH') || exit;
if (!BPM_Portal::manager()) { throw new RuntimeException('Keine Berechtigung.'); }
$points=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.BPM_Portal::table('meter_points').' WHERE unit_id=%d ORDER BY label,id',$u->id));
$endpoint=admin_url('admin-post.php');
?>
<section class="bpm-card"><h2>Messstellen und Zählergeräte</h2><p>Die Messstelle bleibt an der Wohnung. Jedes eingesetzte Gerät besitzt eine eigene Nummer und Gültigkeit. Ein Wechsel erhält beide Geräte und ihre Ablesungen.</p>
<?php if(!$points): ?><p>Noch keine Messstellen vorhanden.</p><?php endif; foreach($points as $p):
$devices=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.BPM_Portal::table('meters').' WHERE point_id=%d AND unit_id=%d ORDER BY installed_on DESC,id DESC',$p->id,$u->id));
$open=array_values(array_filter($devices,static fn($d)=>!$d->removed_on)); ?>
<details class="bpm-thread bpm-point"><summary><?= esc_html($p->label.' · '.$p->unit.' · '.count($devices).' Gerät(e)') ?></summary>
<form method="post" action="<?= esc_url($endpoint) ?>"><?php BPM_Portal::form('point_save'); ?><input type="hidden" name="unit_id" value="<?= (int)$u->id ?>"><input type="hidden" name="point_id" value="<?= (int)$p->id ?>">
<label>Bezeichnung der Messstelle<input name="point_label" required maxlength="160" value="<?= esc_attr($p->label) ?>"></label><label>Einheit<select name="unit"><?php foreach(['m³','kWh','Einheiten'] as $unit): ?><option <?= selected($p->unit,$unit,false) ?>><?= esc_html($unit) ?></option><?php endforeach; ?></select></label><button>Messstelle speichern</button></form>
<h3>Gerätehistorie</h3><?php if(!$devices): ?><p>Noch kein Gerät an dieser Messstelle.</p><?php else: ?><div class="bpm-table-scroll"><table><thead><tr><th>Zählernummer</th><th>Gültig ab</th><th>Gültig bis</th><th>Status</th><th>Letzter Stand</th></tr></thead><tbody>
<?php foreach($devices as $d): $last=$wpdb->get_row($wpdb->prepare('SELECT value,read_at FROM '.BPM_Portal::table('readings').' WHERE meter_id=%d ORDER BY read_at DESC,id DESC LIMIT 1',$d->id));$state=!$d->active?'Inaktiv':($d->installed_on&&$d->installed_on>BPM_Portal::today()?'Geplant':($d->removed_on&&$d->removed_on<BPM_Portal::today()?'Ausgebaut':($d->removed_on?'Endet am '.$d->removed_on:'Im Einsatz'))); ?>
<tr><td><?= esc_html($d->number) ?></td><td><?= $d->installed_on?esc_html(mysql2date('d.m.Y',$d->installed_on)):'Noch unbekannt' ?></td><td><?= $d->removed_on?esc_html(mysql2date('d.m.Y',$d->removed_on)):'Offen' ?></td><td><?= esc_html($state) ?></td><td><?= $last?esc_html(BPM_Domain::reading_display($last->value).' '.$d->unit.' · '.mysql2date('d.m.Y',$last->read_at)):'Noch keine Ablesung' ?></td></tr>
<?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php foreach($devices as $d): ?><details class="bpm-device"><summary><?= esc_html('Gerät '.$d->number.' bearbeiten') ?></summary>
<form method="post" action="<?= esc_url($endpoint) ?>"><?php BPM_Portal::form('device_save'); ?><input type="hidden" name="unit_id" value="<?= (int)$u->id ?>"><input type="hidden" name="point_id" value="<?= (int)$p->id ?>"><input type="hidden" name="meter_id" value="<?= (int)$d->id ?>">
<label>Zählernummer<input name="number" required maxlength="100" value="<?= esc_attr($d->number) ?>"></label><p>Messstelle: <?= esc_html($p->label.' · '.$p->unit) ?></p>
<div class="bpm-columns"><label>Gültig ab<input type="date" name="installed_on" value="<?= esc_attr($d->installed_on ?? '') ?>"></label><label>Gültig bis<input type="date" name="removed_on" value="<?= esc_attr($d->removed_on ?? '') ?>"></label></div><input type="hidden" name="active" value="0"><label class="bpm-check"><input type="checkbox" name="active" value="1" <?= checked($d->active,1,false) ?>>Gerät freigegeben</label><button>Gerät speichern</button></form></details><?php endforeach; ?>
<?php if($open): ?><details class="bpm-exchange"><summary>Zählerwechsel erfassen</summary><p>Der Wechsel schließt das bisherige Gerät ab und legt ein neues Gerät an derselben Messstelle an. Am Wechseltag können End- und Anfangsstand zu den jeweiligen Geräten gespeichert werden.</p>
<form method="post" action="<?= esc_url($endpoint) ?>"><?php BPM_Portal::form('device_exchange'); ?><input type="hidden" name="unit_id" value="<?= (int)$u->id ?>"><input type="hidden" name="point_id" value="<?= (int)$p->id ?>">
<label>Bisheriges Gerät<select name="old_meter_id" required><?php foreach($open as $d): ?><option value="<?= (int)$d->id ?>"><?= esc_html($d->number) ?></option><?php endforeach; ?></select></label><label>Wechseldatum<input type="date" name="change_date" required></label><label>Neue Zählernummer<input name="new_number" required maxlength="100"></label>
<div class="bpm-columns"><label>Endstand bisheriges Gerät (optional)<input name="end_value" inputmode="decimal" placeholder="z. B. 1234,567"></label><label>Anfangsstand neues Gerät (optional)<input name="start_value" inputmode="decimal" placeholder="Tatsächlich abgelesener Stand"></label></div><p class="bpm-small">Ohne eingetragenen Wechselstand wird kein Zählerstand angenommen. Eine eindeutige Mietpartei zum Wechseltag erhält die zugehörige Ablesung; bei Leerstand bleibt sie nur in der Verwaltung.</p><button>Zählerwechsel speichern</button></form></details><?php endif; ?>
<details class="bpm-add-device"><summary><?= $devices?'Weiteres historisches oder geplantes Gerät hinzufügen':'Erstes Gerät hinzufügen' ?></summary><form method="post" action="<?= esc_url($endpoint) ?>"><?php BPM_Portal::form('device_save'); ?><input type="hidden" name="unit_id" value="<?= (int)$u->id ?>"><input type="hidden" name="point_id" value="<?= (int)$p->id ?>"><input type="hidden" name="meter_id" value="0"><input type="hidden" name="active" value="1"><label>Zählernummer<input name="number" required maxlength="100"></label><div class="bpm-columns"><label>Gültig ab<input type="date" name="installed_on" required></label><label>Gültig bis<input type="date" name="removed_on"></label></div><button>Gerät hinzufügen</button></form></details>
</details><?php endforeach; ?></section>
<section class="bpm-card"><h2>Neue Messstelle anlegen</h2><form method="post" action="<?= esc_url($endpoint) ?>"><?php BPM_Portal::form('point_save'); ?><input type="hidden" name="unit_id" value="<?= (int)$u->id ?>"><input type="hidden" name="point_id" value="0"><label>Bezeichnung der Messstelle<input name="point_label" required maxlength="160" placeholder="z. B. Kaltwasser Küche"></label><label>Einheit<select name="unit"><option>m³</option><option>kWh</option><option>Einheiten</option></select></label><button>Messstelle anlegen</button></form></section>
